import{_ as i,o as a,c as t,ae as e}from"./chunks/framework.DQC_QtFV.js";const k=JSON.parse('{"title":"MCP 客户端（OAuth）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mcp.md","filePath":"guide/mcp.md","lastUpdated":1793162416000}'),l={name:"guide/mcp.md"};function n(o,s,p,h,c,d){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="mcp-客户端-oauth" tabindex="-1">MCP 客户端（OAuth） <a class="header-anchor" href="#mcp-客户端-oauth" aria-label="Permalink to &quot;MCP 客户端（OAuth）&quot;">​</a></h1><p>模型可以作为 MCP 客户端。一个用 OAuth 认证的 MCP 服务端可以通过 <strong>Client ID Metadata Document</strong>（CIMD）注册它：<code>client_id</code> 是一个 JSON 文档的 URL， 授权服务器会去取这个文档，从而知道客户端的跳转地址和名字。 <code>client_id</code> 必须与文档被取用时的 URL 完全一致，所以一份文档只能对应一个面板地址。</p><p>下面三种办法按推荐顺序排列。前两种解决&quot;文档放哪&quot;，第三种根本不需要发布文档。</p><h2 id="一、worker-一个地址服务所有面板地址-推荐" tabindex="-1">一、Worker：一个地址服务所有面板地址（推荐） <a class="header-anchor" href="#一、worker-一个地址服务所有面板地址-推荐" aria-label="Permalink to &quot;一、Worker：一个地址服务所有面板地址（推荐）&quot;">​</a></h2><p>仓库里的 <a href="https://github.com/4fuu/personal-bot/tree/main/cimd-worker" target="_blank" rel="noreferrer"><code>cimd-worker/</code></a> 是一个 Cloudflare Worker，它把面板的地址和一个你自己起的 id 一起放进路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://personal-bot-cimd.popoi.work/&lt;id&gt;/http/localhost:8080/mcp-client.json</span></span></code></pre></div><p>就是面板在 <code>http://localhost:8080</code> 时的那份文档：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;client_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://personal-bot-cimd.popoi.work/&lt;id&gt;/http/localhost:8080/mcp-client.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;redirect_uris&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8080/mcp/oauth/callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>URL 由 <strong>id</strong> 和你打开面板时用的地址拼成：id、面板的协议、主机和端口， 再接 <code>/mcp-client.json</code>。控制台的回调路径是固定的（<code>/mcp/oauth/callback</code>）， 变的只有来源，所以来源放在路径里。</p><ul><li>用 <code>openssl rand -hex 16</code> 生成 id：16 到 64 个字符，<code>A-Z a-z 0-9 _ -</code>， 至少一个字母和一个数字。</li><li>之后<strong>一直用同一个</strong>：它是 MCP 服务端注册的 <code>client_id</code> 的一部分， 换一个 id 就是那边的一个新客户端。</li><li>两个人的面板在同一个地址上（比如都是 <code>http://localhost:8080</code>）时，各用各的 id， 否则会注册出同一个 <code>client_id</code>。</li><li>任何来源地址都能用，回环也不例外；畸形的要求（协议不对、路径不对、id 不合规） 才会拿到 400。</li></ul><p>不想依赖上面这个 Worker，就自己部署一个：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cimd-worker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CLOUDFLARE_API_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">有部署</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Worker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 权限的</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Worker 没有依赖，也没有构建步骤。</p><h2 id="二、静态文件-github-pages-上的-mcp-client-json" tabindex="-1">二、静态文件：GitHub Pages 上的 mcp-client.json <a class="header-anchor" href="#二、静态文件-github-pages-上的-mcp-client-json" aria-label="Permalink to &quot;二、静态文件：GitHub Pages 上的 mcp-client.json&quot;">​</a></h2><p>仓库把这份文档放在 <a href="https://github.com/4fuu/personal-bot/blob/main/mcp-client.json" target="_blank" rel="noreferrer"><code>mcp-client.json</code></a>， 文档站把它发布在站点根目录，所以它的地址是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://4fuu.github.io/personal-bot/mcp-client.json</span></span></code></pre></div><p>内容（<code>client_id</code> 就是它自己所在的地址）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;client_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://4fuu.github.io/personal-bot/mcp-client.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;redirect_uris&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:8080/mcp/oauth/callback&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>前提：</strong> 你通过 <code>http://localhost:8080</code> 访问面板。如果你用别的地址访问面板—— 域名、隧道、其他端口——静态文件就不合适了：<code>client_id</code> 必须是被取用时的那个 URL， 所以要么改用上面的 Worker，要么把 <code>redirect_uris</code> 改成与浏览器实际使用的地址完全一致 （授权服务器会拒绝不一致的回调地址）。</p><h2 id="三、什么都不发布" tabindex="-1">三、什么都不发布 <a class="header-anchor" href="#三、什么都不发布" aria-label="Permalink to &quot;三、什么都不发布&quot;">​</a></h2><p>如果不想公开发布任何东西，另外两条路都在面板的 <a href="./console/workspace.html">工作区</a> 页面上：</p><ul><li><strong>动态客户端注册</strong>（<code>dynamic</code>）：授权服务器自己支持时才可用。</li><li><strong>手工注册</strong>（<code>static</code>）：在 MCP 服务端上登记一个 client id 和 secret，填进来。</li></ul><h2 id="在面板里授权" tabindex="-1">在面板里授权 <a class="header-anchor" href="#在面板里授权" aria-label="Permalink to &quot;在面板里授权&quot;">​</a></h2><p>三种办法拿到的都是同一个东西：一个 <code>client_id</code>（第一种是 Worker 的 URL， 第二种是 Pages 的 URL，第三种是手工登记的那对）。然后：</p><ol><li>在 <a href="./console/workspace.html">工作区</a> 页添加或编辑这个 MCP 服务器， 认证选 OAuth，客户端模式选 元数据文档 / 动态注册 / 手工登记 之一。</li><li>点 授权：面板打开授权服务器给的地址，带上它当时算出的跳转地址—— 就是浏览器地址栏里那个来源，不是面板服务端看到的 Host，反代之后两者会不同。</li><li>授权服务器把浏览器送回控制台自己的 <code>/mcp/oauth/callback</code>， 控制台把授权码交给模型换令牌，令牌存在模型侧。</li></ol><p>换到的令牌存在模型那一边，浏览器一个字节都看不到；刷新令牌也在， 所以授过一次权的服务端下次直接是 已授权。stdio 的服务端走不了这条路—— 沙箱里没有浏览器能回来——保存时就会说明。</p>`,26)])])}const u=i(l,[["render",n]]);export{k as __pageData,u as default};
